<?php get_header(); $term=get_queried_object(); $title=is_tax()?single_term_title('',false):'所有店家'; $desc=is_tax()?term_description($term):'探索 BSKTV 收錄的商務 KTV 與酒店店家。'; ?>
<main class="container section"><header class="archive-head"><span class="eyebrow">BSKTV DIRECTORY</span><h1><?php echo esc_html($title); ?></h1><?php if($desc)echo '<div class="archive-desc">'.wp_kses_post($desc).'</div>'; ?></header><div class="filter-bar"><form action="<?php echo esc_url(home_url('/')); ?>" method="get"><input type="search" name="s" placeholder="搜尋店家…" value="<?php echo esc_attr(get_search_query()); ?>"><button class="btn btn-primary" type="submit">搜尋</button></form><div class="filter-links"><?php $cities=get_terms(array('taxonomy'=>'bsktv_city','hide_empty'=>true,'number'=>8));foreach($cities as $city)echo '<a href="'.esc_url(get_term_link($city)).'">'.esc_html($city->name).'</a>'; ?></div></div><?php if(have_posts()): ?><div class="store-grid"><?php while(have_posts()):the_post();get_template_part('template-parts/store-card');endwhile; ?></div><?php the_posts_pagination(array('mid_size'=>1,'prev_text'=>'←','next_text'=>'→')); else: ?><div class="empty-state"><h2>目前沒有符合條件的店家</h2><p>換個關鍵字或城市再試試。</p></div><?php endif; ?></main><?php get_footer(); ?>
